-- Public reviewer SQL: supply review_cohort(stay_id,hadm_id,subject_id,t0).
-- The Python runner binds the same authorized keys with a VALUES CTE instead.
WITH keys(stay_id,hadm_id,subject_id,t0) AS (SELECT stay_id,hadm_id,subject_id,t0 FROM review_cohort), c AS (SELECT k.*,i.intime,i.outtime,GREATEST(i.intime,k.t0-interval '24 hour') ws FROM keys k JOIN mimiciv_icu.icustays i USING(stay_id)) SELECT * FROM (SELECT c.stay_id,v.variable,v.value::float8,x.charttime charttime,NULL::timestamp endtime,'vitalsign' source,'{}'::jsonb metadata FROM c JOIN mimiciv_derived.vitalsign x ON c.stay_id=x.stay_id AND x.charttime>=c.ws AND x.charttime<c.t0 CROSS JOIN LATERAL (VALUES ('map',mbp),('temperature',temperature),('heart_rate',heart_rate),('resp_rate',resp_rate)) v(variable,value) WHERE (true) AND v.value IS NOT NULL UNION ALL SELECT c.stay_id,v.variable,v.value::float8,x.charttime charttime,NULL::timestamp endtime,'chemistry' source,'{}'::jsonb metadata FROM c JOIN mimiciv_derived.chemistry x ON c.hadm_id=x.hadm_id AND x.charttime>=c.ws AND x.charttime<c.t0 CROSS JOIN LATERAL (VALUES ('creatinine',creatinine),('sodium',sodium),('potassium',potassium),('bicarbonate',bicarbonate)) v(variable,value) WHERE (x.subject_id=c.subject_id) AND v.value IS NOT NULL UNION ALL SELECT c.stay_id,v.variable,v.value::float8,x.charttime charttime,NULL::timestamp endtime,'enzyme' source,'{}'::jsonb metadata FROM c JOIN mimiciv_derived.enzyme x ON c.hadm_id=x.hadm_id AND x.charttime>=c.ws AND x.charttime<c.t0 CROSS JOIN LATERAL (VALUES ('bilirubin',bilirubin_total)) v(variable,value) WHERE (x.subject_id=c.subject_id) AND v.value IS NOT NULL UNION ALL SELECT c.stay_id,v.variable,v.value::float8,x.charttime charttime,NULL::timestamp endtime,'complete_blood_count' source,'{}'::jsonb metadata FROM c JOIN mimiciv_derived.complete_blood_count x ON c.hadm_id=x.hadm_id AND x.charttime>=c.ws AND x.charttime<c.t0 CROSS JOIN LATERAL (VALUES ('platelet',platelet),('hematocrit',hematocrit),('wbc',wbc)) v(variable,value) WHERE (x.subject_id=c.subject_id) AND v.value IS NOT NULL UNION ALL SELECT c.stay_id,v.variable,v.value::float8,x.charttime charttime,NULL::timestamp endtime,'gcs' source,jsonb_build_object('motor',gcs_motor,'eyes',gcs_eyes,'verbal',gcs_verbal,'unable',gcs_unable) metadata FROM c JOIN mimiciv_derived.gcs x ON c.stay_id=x.stay_id AND x.charttime>=c.ws AND x.charttime<c.t0 CROSS JOIN LATERAL (VALUES ('gcs',gcs)) v(variable,value) WHERE (true) AND v.value IS NOT NULL UNION ALL SELECT c.stay_id,v.variable,v.value::float8,x.charttime charttime,NULL::timestamp endtime,'bg' source,jsonb_build_object('vent',EXISTS(SELECT 1 FROM mimiciv_derived.ventilation vd WHERE vd.stay_id=c.stay_id AND vd.starttime<=x.charttime AND vd.endtime>=x.charttime AND vd.ventilation_status='InvasiveVent'),'po2',po2,'pco2',pco2,'fio2',fio2,'fio2_chart',fio2_chartevents,'aado2',aado2_calc,'ph',ph) metadata FROM c JOIN mimiciv_derived.bg x ON c.hadm_id=x.hadm_id AND x.charttime>=c.ws AND x.charttime<c.t0 CROSS JOIN LATERAL (VALUES ('pf',pao2fio2ratio)) v(variable,value) WHERE (x.specimen='ART.' AND x.subject_id=c.subject_id) AND v.value IS NOT NULL UNION ALL SELECT c.stay_id,v.variable,v.value::float8,x.charttime charttime,NULL::timestamp endtime,'urine_output_rate' source,jsonb_build_object('hours',uo_tm_24hr,'period_start',x.charttime-uo_tm_24hr*interval '1 hour') metadata FROM c JOIN mimiciv_derived.urine_output_rate x ON c.stay_id=x.stay_id AND x.charttime>=c.ws AND x.charttime<c.t0 CROSS JOIN LATERAL (VALUES ('urine24',urineoutput_24hr)) v(variable,value) WHERE (true) AND v.value IS NOT NULL UNION ALL SELECT c.stay_id,'dopamine',x.vaso_rate::float8,GREATEST(x.starttime,c.ws),LEAST(x.endtime,c.t0),'dopamine',jsonb_build_object('rate_unit','mcg/kg/min','original_start',x.starttime,'original_end',x.endtime) FROM c JOIN mimiciv_derived.dopamine x ON c.stay_id=x.stay_id AND x.starttime<c.t0 AND x.endtime>c.ws WHERE x.vaso_rate>0 UNION ALL SELECT c.stay_id,'dobutamine',x.vaso_rate::float8,GREATEST(x.starttime,c.ws),LEAST(x.endtime,c.t0),'dobutamine',jsonb_build_object('rate_unit','mcg/kg/min','original_start',x.starttime,'original_end',x.endtime) FROM c JOIN mimiciv_derived.dobutamine x ON c.stay_id=x.stay_id AND x.starttime<c.t0 AND x.endtime>c.ws WHERE x.vaso_rate>0 UNION ALL SELECT c.stay_id,'epinephrine',x.vaso_rate::float8,GREATEST(x.starttime,c.ws),LEAST(x.endtime,c.t0),'epinephrine',jsonb_build_object('rate_unit','mcg/kg/min','original_start',x.starttime,'original_end',x.endtime) FROM c JOIN mimiciv_derived.epinephrine x ON c.stay_id=x.stay_id AND x.starttime<c.t0 AND x.endtime>c.ws WHERE x.vaso_rate>0 UNION ALL SELECT c.stay_id,'norepinephrine',x.vaso_rate::float8,GREATEST(x.starttime,c.ws),LEAST(x.endtime,c.t0),'norepinephrine',jsonb_build_object('rate_unit','mcg/kg/min','original_start',x.starttime,'original_end',x.endtime) FROM c JOIN mimiciv_derived.norepinephrine x ON c.stay_id=x.stay_id AND x.starttime<c.t0 AND x.endtime>c.ws WHERE x.vaso_rate>0 UNION ALL SELECT c.stay_id,CASE x.itemid WHEN 220739 THEN 'gcs_raw_eyes' WHEN 223900 THEN 'gcs_raw_verbal' ELSE 'gcs_raw_motor' END,x.valuenum::float8,x.charttime,NULL::timestamp,'chartevents',jsonb_build_object('storetime',x.storetime,'ett',x.value='No Response-ETT') FROM c JOIN mimiciv_icu.chartevents x ON c.stay_id=x.stay_id AND x.subject_id=c.subject_id AND x.charttime>=c.ws AND x.charttime<c.t0 AND x.itemid IN (220739,223900,223901) WHERE x.valuenum IS NOT NULL) obs ORDER BY stay_id,charttime,variable;